package slug

import (
	"strings"
	"unicode"
)

// Slugify lowercases s, collapses every run of whitespace into a single
// underscore, and drops every character that is not a letter, a digit, or
// an underscore.
func Slugify(s string) string {
	s = strings.ToLower(s)

	var b strings.Builder
	inSpace := false
	for _, r := range s {
		if unicode.IsSpace(r) {
			inSpace = true
			continue
		}
		if inSpace {
			b.WriteByte('_')
			inSpace = false
		}
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' {
			b.WriteRune(r)
		}
	}
	if inSpace {
		b.WriteByte('_')
	}

	return b.String()
}

